--
-- Name: teachers; Type: TABLE; Schema: schoolers; Owner: ravi
--

CREATE TABLE schoolers.teachers (
    teacher_id integer NOT NULL,
    school_id integer NOT NULL,
    name character varying(100) NOT NULL,
    role_title character varying(100) NOT NULL,
    phone character varying(30) NOT NULL,
    email character varying(120),
    attendance_status character varying(15) DEFAULT 'On time'::character varying NOT NULL,
    created_at timestamp without time zone DEFAULT now() NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    present_address character varying(255),
    permanent_address character varying(255),
    date_of_birth date,
    emergency_number character varying(30),
    gender character varying(20),
    CONSTRAINT teachers_attendance_status_check CHECK (((attendance_status)::text = ANY (ARRAY[('On time'::character varying)::text, ('On leave'::character varying)::text, ('Absent'::character varying)::text])))
);


ALTER TABLE schoolers.teachers OWNER TO ravi;

--
