--

CREATE SEQUENCE schoolers.teachers_teacher_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


ALTER SEQUENCE schoolers.teachers_teacher_id_seq OWNER TO ravi;

--
-- Name: teachers_teacher_id_seq; Type: SEQUENCE OWNED BY; Schema: schoolers; Owner: ravi
--

ALTER SEQUENCE schoolers.teachers_teacher_id_seq OWNED BY schoolers.teachers.teacher_id;


--
-- Name: timetable_entries; Type: TABLE; Schema: schoolers; Owner: ravi
